        public void PadAffordable(Transform pad) => Punch.Scale(pad, affordablePunch);

        /// <summary>Delay of the <paramref name="order"/>-th item when several drop in together.</summary>
        public float DropDelay(int order) => order * dropStagger;

        /// <summary>Delay of the <paramref name="order"/>-th of <paramref name="count"/> items torn down together.</summary>
        public float TearDownDelay(int order, int count) => count > 1 ? teardownSpread * order / (count - 1) : 0f;

        /// <summary>Drops a freshly placed item in from above; it lands with a squash, dust, confetti and a shake.</summary>
        /// <param name="rest">Where the item stands once landed (its parent's space).</param>
        /// <param name="shake">Shake the camera on landing (the local player's own plot).</param>
        public void DropIn(Transform item, Vector3 rest, float delay, bool shake) => Begin(item, rest, DropRoutine(item, rest, delay, shake, false));

        /// <summary>
        /// A kept item on rebirth: it collapses with the rest of the build, then drops back in after
        /// <paramref name="delay"/>.
        /// </summary>
        public void Rebuild(Transform item, Vector3 rest, float vanishDelay, float delay, bool shake) =>
            Begin(item, rest, DropRoutine(item, rest, delay, shake, true, vanishDelay));

        void Begin(Transform item, Vector3 rest, IEnumerator routine) {
            Punch.Cancel(item);
            pendingDrops[item] = new Rest(rest, item.localScale);
            StartCoroutine(routine);
        }

        IEnumerator DropRoutine(Transform item, Vector3 rest, float delay, bool shake, bool vanishFirst, float vanishDelay = 0f) {
            Vector3 up = item.parent != null ? item.parent.InverseTransformDirection(Vector3.up) : Vector3.up;
            float wait = delay;
            if (vanishFirst) {
                Vector3 scale = item.localScale;
                if (vanishDelay > 0f) yield return new WaitForSeconds(vanishDelay);
                if (item == null) yield break;
                yield return Collapse(item);
                if (item == null) yield break;
                item.localScale = scale;
                item.localPosition = rest;
                wait -= vanishDelay + teardownSeconds;
            }
            if (wait > 0f) {
                item.gameObject.SetActive(false);
                yield return new WaitForSeconds(wait);
                if (item == null) yield break;
                item.gameObject.SetActive(true);
            }
            for (float t = 0f; t < 1f; t += Time.deltaTime / dropSeconds) {
                if (item == null) yield break;
                item.localPosition = rest + up * (dropHeight * (1f - t * t));
                yield return null;
            }
            if (item == null) yield break;
            item.localPosition = rest;
            pendingDrops.Remove(item);
            Landed(item, shake);
        }

        void Landed(Transform item, bool shake) {
            Punch.Squash(item, landingSquash, landingSquashSeconds);
            (Vector3 centre, float scale, _) = Footprint(item);
            PuffAlongParts(FxKind.DustPuff, item, dustColor, 1f);
            GameFx.Play(FxKind.Confetti, centre + Vector3.up * confettiHeight, confettiColor, scale);
            GameSfx.PlayAt(SfxCue.Build, centre);
            if (shake) CameraShake.Explosion(centre, landingShakeRadius, landingShake, landingShakeSeconds);
        }

        /// <summary>Ground point under the item's visible centre, an effect scale for its size, and its width.</summary>
        (Vector3 centre, float scale, float size) Footprint(Transform item) {
            item.GetComponentsInChildren(RendererBuffer);
            if (RendererBuffer.Count == 0) return (item.position, landingFxScale, 0f);
            Bounds bounds = RendererBuffer[0].bounds;
            for (int i = 1; i < RendererBuffer.Count; i++) bounds.Encapsulate(RendererBuffer[i].bounds);
            float size = Mathf.Max(bounds.size.x, bounds.size.z);
            return (new Vector3(bounds.center.x, item.position.y, bounds.center.z), EffectScale(size), size);
        }

        /// <summary>
        /// One puff on the ground under each part of the item (up to <see cref="maxPartPuffs"/>, spread
        /// evenly), sized to that part: a wall run puffs along its whole length, not in the plot's middle.
        /// </summary>
        void PuffAlongParts(FxKind kind, Transform item, Color color, float scale) {
            item.GetComponentsInChildren(RendererBuffer);
            int parts = RendererBuffer.Count, puffs = Mathf.Min(parts, maxPartPuffs);
            for (int i = 0; i < puffs; i++) {
                Bounds part = RendererBuffer[parts * i / puffs].bounds;
                Vector3 ground = new(part.center.x, item.position.y, part.center.z);
                GameFx.Play(kind, ground, color, scale * EffectScale(Mathf.Max(part.size.x, part.size.z)));
            }
        }

        float EffectScale(float size) => landingFxScale * Mathf.Clamp(size / landingFxReferenceSize, landingFxScaleRange.x, landingFxScaleRange.y);

        /// <summary>Collapses an item in a puff of smoke, then destroys it.</summary>
        public void TearDown(GameObject item, float delay) {
            pendingTeardowns.Add(item);
            StartCoroutine(TearDownRoutine(item, delay));
        }

        IEnumerator TearDownRoutine(GameObject item, float delay) {
            if (delay > 0f) yield return new WaitForSeconds(delay);
            if (item == null) yield break;
            yield return Collapse(item.transform);
            pendingTeardowns.Remove(item);
            if (item != null) Destroy(item);
        }

        /// <summary>
        /// Light smoke along the item's parts (smoke only: a whole build collapses at once, so one effect per part), then a wide item (a wall run, a building row) sinks flat into
        /// the floor while a small one shrinks about its own centre, so nothing slides across the plot.
        /// </summary>
        IEnumerator Collapse(Transform t) {
            Punch.Cancel(t);
            (Vector3 centre, _, float size) = Footprint(t);
            PuffAlongParts(FxKind.Smoke, t, teardownSmokeColor, teardownSmokeScale);
            bool flatten = size > teardownFlattenSize;
            Vector3 startScale = t.localScale, startPosition = t.position;
            for (float a = 0f; a < 1f; a += Time.deltaTime / teardownSeconds) {
                if (t == null) yield break;
                float keep = 1f - a * a;
                if (flatten) {
                    t.localScale = new Vector3(startScale.x, startScale.y * keep, startScale.z);
                } else {
                    t.localScale = startScale * keep;
                    t.position = centre + (startPosition - centre) * keep;
                }
                yield return null;
            }
            if (t != null) t.localScale = Vector3.zero;
        }

        // ---------------------------------------------------------------- rebirth and events
        /// <summary>What everyone nearby sees when a plot rebirths: shockwave, confetti, a boom and a shake.</summary>
        public void RebirthWorld(Vector3 plotCentre) {
            GameFx.Play(FxKind.ShockwaveRing, plotCentre, rebirthColor, shockwaveScale);
            GameFx.Play(FxKind.Confetti, plotCentre + Vector3.up * rebirthConfettiHeight, rebirthColor, rebirthConfettiScale);
            GameSfx.PlayAt(SfxCue.ExplosionLarge, plotCentre);
            CameraShake.Explosion(plotCentre, rebirthShakeRadius, rebirthShake);
        }

        /// <summary>The rebirthing player's own screen: flash, banner and fanfare.</summary>
        public void RebirthScreen(int rebirths) {
            ScreenFx.Flash(rebirthFlash, rebirthFlashSeconds);
            ScreenFx.ShowText($"REBIRTH {rebirths}!", rebirthColor, bannerSeconds, bannerSize);
            GameSfx.Play(SfxCue.Win);
        }

        /// <param name="multiplier">The server's rush multiplier, or 0 when not known yet (the banner then leaves it out).</param>
        public void RushStarted(float multiplier) {
            ScreenFx.Flash(rushFlash);
            ScreenFx.ShowText(multiplier > 1f ? $"RUSH x{multiplier:0.#}" : "RUSH HOUR", rushColor, bannerSeconds, bannerSize);
            GameSfx.Play(SfxCue.Horn);
        }

        public void RushEnded() => GameSfx.Play(SfxCue.Whoosh, rushEndVolume);

        // ---------------------------------------------------------------- landmarks and the Brick Rocket
        /// <summary>The local player built a landmark (a rebirth milestone's reward): banner, flash, gold confetti, a punch.</summary>
        public void LandmarkBuilt(Vector3 landmark, string name) {
            ScreenFx.Flash(landmarkFlash);
            ScreenFx.ShowText($"{name.ToUpperInvariant()}!", landmarkColor, bannerSeconds, bannerSize);
            GameSfx.Play(SfxCue.Win);
            StartCoroutine(LandmarkLanded(landmark));
        }

        IEnumerator LandmarkLanded(Vector3 landmark) {
            // When the model lands (it drops in once the plot update arrives).
            yield return new WaitForSeconds(dropSeconds + 0.15f);
            GameFx.Play(FxKind.Confetti, landmark + Vector3.up * 3f, landmarkColor, landmarkConfettiScale);
            GameFx.Play(FxKind.ShockwaveRing, landmark, landmarkColor, shockwaveScale * 0.6f);
            CameraShake.Explosion(landmark, landingShakeRadius, landmarkShake);
        }

        /// <summary>
        /// The Brick Rocket's launch: once it has landed, a countdown, ignition, a climb on a trail of fire,
        /// fireworks at the top, and then it lands back on its pad (it is a landmark: it stays).
        /// </summary>
        public void LaunchRocket(TY_RocketView view) {
            if (view != null && view.rocket != null) StartCoroutine(LaunchRoutine(view));
        }

        IEnumerator LaunchRoutine(TY_RocketView view) {
            Transform root = view.transform, rocket = view.rocket;
            while (root != null && pendingDrops.ContainsKey(root)) yield return null;
            yield return new WaitForSeconds(rocketPause);
            for (int n = 3; n >= 1; n--) {
                if (rocket == null) yield break;
                ScreenFx.ShowText(n.ToString(), landmarkColor, rocketCountStep * 0.9f, bannerSize);
                GameSfx.PlayAt(SfxCue.CountdownBeep, rocket.position);
                yield return new WaitForSeconds(rocketCountStep);
            }
            if (rocket == null) yield break;
            Vector3 rest = rocket.localPosition;
            Vector3 pad = rocket.position;
            Transform nozzle = view.nozzle != null ? view.nozzle : rocket;
            ScreenFx.ShowText("LIFTOFF!", landmarkColor, bannerSeconds, bannerSize);
            GameSfx.PlayAt(SfxCue.Go, pad);
            GameSfx.PlayAt(SfxCue.ExplosionLarge, pad);
            GameFx.Play(FxKind.ExplosionSmall, nozzle.position, rocketFlame, 1.5f);
            for (int i = 0; i < 4; i++) {
                Vector2 o = Random.insideUnitCircle * 2.2f;
                GameFx.Play(FxKind.Smoke, pad + new Vector3(o.x, 0.2f, o.y), teardownSmokeColor, 2.5f);
            }
            GameFx.Play(FxKind.ShockwaveRing, pad, rocketFlame, shockwaveScale);
            CameraShake.Explosion(pad, rocketShakeRadius, 0.9f, 1.2f);
            FxHandle trail = GameFx.Attach(FxKind.Trail, nozzle, Vector3.zero, rocketFlame, rocketTrailScale);
            Vector3 up = rocket.parent != null ? rocket.parent.InverseTransformDirection(Vector3.up) : Vector3.up;
            for (float t = 0f; t < 1f; t += Time.deltaTime / rocketClimbSeconds) {
                if (rocket == null) { trail.Stop(); yield break; }
                // Slow off the pad, then faster and faster, with a slight wobble.
                float wobble = Mathf.Sin(t * 40f) * 0.04f * (1f - t);
                rocket.localPosition = rest + up * (rocketHeight * t * t * t);
                rocket.localRotation = Quaternion.Euler(wobble * 30f, 0f, wobble * 20f);
                yield return null;
            }
            trail.Stop();
            if (rocket == null) yield break;
            Vector3 top = rocket.position;
            GameFx.Play(FxKind.ExplosionLarge, top, landmarkColor, 3f);
            GameFx.Play(FxKind.Confetti, top, landmarkColor, landmarkConfettiScale * 2f);
            GameSfx.Play(SfxCue.ExplosionLarge, 0.8f);
            GameSfx.Play(SfxCue.Win);
            rocket.gameObject.SetActive(false);
            rocket.localRotation = Quaternion.identity;
            yield return new WaitForSeconds(rocketAwaySeconds);
            if (rocket == null) yield break;
            rocket.localPosition = rest;
            rocket.gameObject.SetActive(true);
            DropIn(rocket, rest, 0f, true);
        }

        // ---------------------------------------------------------------- goals, chest, welcome back
        /// <param name="paidTokens">The goal paid perk tokens: the bigger fanfare.</param>
        public void GoalCompleted(bool paidTokens) {
            ScreenFx.Flash(goalFlash);
            GameSfx.Play(paidTokens ? SfxCue.LevelUp : SfxCue.Purchase, goalVolume);
        }

        /// <summary>The local player opened today's chest: a gold burst, confetti and a long cash-register run.</summary>
        public void ChestOpened(Vector3 chest, long amount) {
            MoneyPopup(chest, amount, popupSize * coinPopupScale);
            GameFx.Play(FxKind.CoinBurst, chest + Vector3.up, chestColor, chestBurstScale);
            GameFx.Play(FxKind.Confetti, chest + Vector3.up * confettiHeight, chestColor, chestConfettiScale);
            GameSfx.PlayAt(SfxCue.Win, chest);
            StartCoroutine(RegisterRun(chest, chestRegisterCoins));
        }

        /// <summary>The "while you were away" card opened.</summary>
        public void WelcomeBack() => GameSfx.Play(SfxCue.LevelUp);

        /// <summary>The "while you were away" card closed: the cash lands in the wallet.</summary>
        public void OfflineCollected(long amount) {
            if (amount > 0) StartCoroutine(ScreenRegisterRun(offlineRegisterCoins));
        }

        /// <summary>A cash-register run heard on screen (2D), for money that lands in the wallet, not on the plot.</summary>
        IEnumerator ScreenRegisterRun(int coins) {
            var wait = new WaitForSeconds(registerCoinSpacing);
            for (int i = 0; i < coins; i++) {
                register.Play();
                yield return wait;
            }
        }
    }
}
